use moloch_live_runtime::{dispatch,feedback,quote_priority};
#[path="../src/stale_entry_drafts.rs"]mod stale_entry_drafts;
use stale_entry_drafts::*;
use dispatch::DispatchLog;
use moloch_replay::session::Session;
use baal_transport_service::Scope;
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeSet,path::PathBuf,sync::atomic::{AtomicU64,Ordering}};
const BASE:u64=1_792_054_800_000;
fn iso(t:u64)->String{chrono::DateTime::from_timestamp_millis((BASE+t)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
struct F{root:PathBuf,bank:Session,log:DispatchLog,scope:Scope}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
impl F{
 fn new()->Self{static N:AtomicU64=AtomicU64::new(0);let root=std::env::temp_dir().join(format!("stale-entry-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),N.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir_all(&root).unwrap();let policy=json!({"initialCash":"1000.000000","maximumCommitted":"1000.000000","maximumMarketCost":"500.000000","quantity":10,"maximumMarkets":4,"entryStopAt":iso(3600000),"lifetimeMs":600000});let seed=json!({"runId":"stale-fixture","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();let log=DispatchLog::open(&root.join("dispatch.ndjson")).unwrap();let scope=Scope{tournament_id:"cup".into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into()),("102".into(),"102".into())].into()};Self{root,bank,log,scope}}
 fn put(&mut self,e:&Value){let n=self.bank.last_source_sequence("fixture")+1;self.bank.accept("fixture",n,e).unwrap();}
 fn book(&mut self,ex:&str,t:u64){self.put(&json!({"type":"book","receivedAt":iso(t),"book":{"marketId":ex,"exchangeId":ex,"tournamentId":"cup","sequence":(t+1).to_string(),"sourceAt":iso(t),"requestStartedAt":iso(t),"receivedAt":iso(t),"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}}));}
 fn selected(&self,t:u64)->Selection{select(&self.bank,&self.log,&self.scope,&BTreeSet::new(),BASE+t).unwrap()}
 fn q(&self)->Value{self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["side"]=="YES").unwrap()}
 fn intent(&mut self,q:&Value){self.log.append(json!({"kind":"intent","qid":q["id"],"quote":q,"at":iso(3000),"spec":{"method":"POST","endpoint":"/orders","body":{"exchangeId":q["exchangeId"],"side":"yes","action":"buy","quantity":q["quantity"],"price":0.4}},"permit":{"runId":"stale-fixture","intentId":q["id"].to_string(),"owner":"Codex","expiresAtMs":BASE+600000,"maximumQuantity":10,"maximumCost":"4.000000"}})).unwrap();}
 fn ack(&mut self,q:&Value){self.intent(q);self.log.append(json!({"kind":"attempt","qid":q["id"],"at":iso(3000)})).unwrap();let e=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"b".repeat(64),"orderId":q["id"],"actualOrderId":"991","exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":"buy","quantity":q["quantity"],"price":q["price"],"receivedAt":iso(3000)});self.put(&e);self.log.append(json!({"kind":"ack","qid":q["id"],"receipt":{"endpoint":"/orders","status":200,"requestStartedAt":iso(3000),"receivedAt":iso(3000),"data":{"orderId":991,"open":true,"exchangeId":q["exchangeId"],"side":"yes","action":"buy","quantity":q["quantity"],"price":0.4,"quantityTraded":0}}})).unwrap();}
 fn terminal(&mut self,q:&Value,filled:u64){self.put(&json!({"type":"actual_order_terminal","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderReceiptHash":"d".repeat(64),"orderId":q["id"],"actualOrderId":"991","exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":"buy","status":"canceled","filledQuantity":filled,"fillsComplete":true,"receivedAt":iso(5000)}));self.log.append(json!({"kind":"closed","qid":q["id"],"orderReceiptHash":"d".repeat(64),"fillReceiptHash":"c".repeat(64)})).unwrap();}
}
#[test]fn exact_sixty_second_boundary_and_principal_do_not_mutate_bank_or_original_log(){let mut f=F::new();f.book("101",0);let report=f.bank.engine().report().unwrap();let descriptor=f.log.descriptor_identity().unwrap();assert!(f.selected(59999).drafts().is_empty());let s=f.selected(60000);assert_eq!(s.drafts().len(),2);assert_eq!(s.drafts().iter().map(Draft::reserved_units).sum::<i128>(),9_500_000);assert!(s.drafts()[0].reserved_units()>=s.drafts()[1].reserved_units());assert_eq!(s.native_head(),&f.bank.durable_head());assert_eq!(s.dispatch_descriptor_identity(),&descriptor);s.validate_current(&f.bank,&f.log,&f.scope,&BTreeSet::new(),BASE+60000).unwrap();assert_eq!(f.bank.engine().report().unwrap(),report);assert_eq!(f.log.descriptor_identity().unwrap(),descriptor);assert_eq!(MINIMUM_DRAFT_AGE_MS,60000);}
#[test]fn genuine_fresh_book_is_not_cleanup_even_for_old_unfilled_quotes(){let mut f=F::new();f.book("101",0);f.book("101",60000);assert!(f.selected(60000).drafts().is_empty());}
#[test]fn original_gap_is_read_unavailability_and_never_a_price_or_cash_credit(){let mut f=F::new();f.book("101",0);f.put(&json!({"type":"gap","exchangeIds":["101"],"receivedAt":iso(60000)}));let before=f.bank.engine().report().unwrap();let s=f.selected(60000);assert_eq!(s.drafts().len(),2);assert_eq!(f.bank.engine().report().unwrap(),before);assert_eq!(before["cash"],"1000.000000");}
#[test]fn intervening_native_event_or_original_dispatch_append_invalidates_selection(){for kind in ["native","dispatch"]{let mut f=F::new();f.book("101",0);let s=f.selected(60000);if kind=="native"{f.put(&json!({"type":"tick","receivedAt":iso(60001)}));}else{f.intent(s.drafts()[0].quote());}assert!(s.validate_current(&f.bank,&f.log,&f.scope,&BTreeSet::new(),BASE+60001).is_err(),"{kind}");}}
#[test]fn changed_managed_scope_and_clock_regression_fail_closed(){let mut f=F::new();f.book("101",0);let s=f.selected(60000);let managed=["101".into()].into();assert!(select(&f.bank,&f.log,&f.scope,&managed,BASE+60000).unwrap().drafts().is_empty());assert!(s.validate_current(&f.bank,&f.log,&f.scope,&managed,BASE+60000).is_err());assert!(s.validate_current(&f.bank,&f.log,&f.scope,&BTreeSet::new(),BASE+59999).is_err());let mut scope=f.scope.clone();scope.exchanges.insert("101".into(),"999".into());assert!(select(&f.bank,&f.log,&scope,&BTreeSet::new(),BASE+60000).is_err());assert!(select(&f.bank,&f.log,&f.scope,&["999".into()].into(),BASE+60000).is_err());}
#[test]fn durable_intent_without_attempt_is_not_a_never_intended_cleanup_candidate(){let mut f=F::new();f.book("101",0);let q=f.q();f.intent(&q);assert!(f.selected(60000).drafts().iter().all(|d|d.qid()!=q["id"].as_u64().unwrap()));}
#[test]fn unresolved_original_attempt_fails_closed_without_releasing_mate_or_other_scope(){let mut f=F::new();f.book("101",0);let q=f.q();f.intent(&q);f.log.append(json!({"kind":"attempt","qid":q["id"],"at":iso(3000)})).unwrap();let before=f.bank.engine().report().unwrap();assert!(select(&f.bank,&f.log,&f.scope,&BTreeSet::new(),BASE+60000).is_err());assert_eq!(f.bank.engine().report().unwrap(),before);}
#[test]fn actual_pending_buy_protects_never_sent_opposite_mate_until_original_terminal(){let mut f=F::new();f.book("101",0);f.book("102",0);let q=f.q();f.ack(&q);assert!(f.selected(60000).drafts().iter().all(|d|d.quote()["exchangeId"]!="101"));f.terminal(&q,0);assert!(f.selected(60000).drafts().iter().any(|d|d.quote()["exchangeId"]=="101"));}
#[test]fn actual_partial_fill_then_terminal_preserves_owned_inventory_and_opposite_cover(){let mut f=F::new();f.book("101",0);let q=f.q();f.ack(&q);f.put(&json!({"type":"actual_fill","source":"official_sig_api_v1","receiptHash":"e".repeat(64),"orderId":q["id"],"actualOrderId":"991","exchangeId":"101","marketId":"101","side":"YES","action":"buy","quantity":2,"price":"0.400000","fee":"0.000000","fillId":"881","executedAt":iso(4000),"receivedAt":iso(4000)}));f.terminal(&q,2);let report=f.bank.engine().report().unwrap();assert!(f.selected(60000).drafts().is_empty());assert_eq!(f.bank.engine().wallet.quantity("101",moloch_replay::Side::Yes),2);assert_eq!(f.bank.engine().report().unwrap(),report);}
#[test]fn typed_unknown_package_retains_all_funding_and_is_not_ordinary_stale_cleanup(){let mut f=F::new();f.book("101",0);f.book("102",0);for q in f.bank.engine().order_records(){f.log.append(json!({"kind":"not_sent","qid":q["id"],"proof":f.log.proof(q["id"].as_u64().unwrap())})).unwrap();f.put(&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"confirmedNetworkAttempts":0,"receiptHash":"e".repeat(64),"deferPlanningForPackage":true,"receivedAt":iso(1)}));}let hashes=f.bank.engine().live_package_books().into_iter().map(|b|(b["exchangeId"].as_str().unwrap().to_owned(),hash(&b))).collect::<std::collections::BTreeMap<_,_>>();let scope=json!({"runId":"stale-fixture","bankManifestHash":f.bank.manifest_hash(),"tournamentId":"cup"});f.put(&json!({"type":"live_package_reserve","source":"moloch_live_dispatcher","receivedAt":iso(1),"processedAt":iso(1),"packageId":"protected","proofHash":"a".repeat(64),"bankScope":scope,"expiresAt":iso(120000),"economics":{"maximumCost":"4.500000","minimumPayout":"5.000000","minimumSurplus":"0.500000","feeTotal":"0.000000"},"legs":[{"marketId":"101","exchangeId":"101","side":"YES","quantity":5,"limitPrice":"0.450000","bookHash":hashes["101"]},{"marketId":"102","exchangeId":"102","side":"YES","quantity":5,"limitPrice":"0.450000","bookHash":hashes["102"]}]}));f.put(&json!({"type":"live_package_attempt","source":"moloch_live_dispatcher","receivedAt":iso(3001),"processedAt":iso(3001),"packageId":"protected","proofHash":"a".repeat(64),"bankScope":scope,"requestHash":"b".repeat(64),"idempotencyKey":"stale-protected","bookHashes":hashes}));f.put(&json!({"type":"live_package_unknown","source":"moloch_live_dispatcher","receivedAt":iso(3002),"packageId":"protected","proofHash":"a".repeat(64),"bankScope":scope,"requestHash":"b".repeat(64)}));let before=f.bank.engine().report().unwrap();assert!(f.selected(60000).drafts().is_empty());assert_eq!(f.bank.engine().report().unwrap(),before);assert_eq!(before["reservedCash"],"4.500000");assert!(f.bank.engine().package_blocks_submissions());}
